+                       {                                                                                                          \
+                               if (!(condition))                                                                                      \
+                               {                                                                                                      \
+                                       std::stringstream ss;                                                                              \
+                                       ss << "[PCPP] Assertion failed on [" << __FILE__ << ":" << __LINE__ << "] with: " << (message);    \
