   220  bool Packet::insertLayer(Layer* prevLayer, Layer* newLayer, bool ownInPacket)
   220  bool Packet::insertLayer(Layer* prevLayer, Layer* newLayer, bool ownInPacket)
   221  {
   222          if (newLayer == nullptr)
   223          {
   224                  PCPP_LOG_ERROR("Layer to add is NULL");
   225                  return false;
   226          }
   227
   228          if (newLayer->isAllocatedToPacket())
   229          {
   230                  PCPP_LOG_ERROR("Layer is already allocated to another packet. Cannot use layer in more than one packet");
   231                  return false;
   232          }
   233
   234          if (prevLayer != nullptr && prevLayer->getProtocol() == PacketTrailer)
   235          {
   236                  PCPP_LOG_ERROR("Cannot insert layer after packet trailer");
   237                  return false;
   238          }
   239
   240          size_t newLayerHeaderLen = newLayer->getHeaderLen();
   241          if (m_RawPacket->getRawDataLen() + newLayerHeaderLen > m_MaxPacketLen)
   242          {
   243                  if (!m_CanReallocateData)
   244                  {
   245                          PCPP_LOG_ERROR("With the new layer the packet will exceed the size of the pre-allocated buffer: " << m_MaxPacketLen << " bytes");
   246                          return false;
   247                  }
   248                  // reallocate to maximum value of: twice the max size of the packet or max size + new required length
   249                  if (m_RawPacket->getRawDataLen() + newLayerHeaderLen > m_MaxPacketLen*2)
   250                          reallocateRawData(m_RawPacket->getRawDataLen() + newLayerHeaderLen + m_MaxPacketLen);
   251                  else
   252                          reallocateRawData(m_MaxPacketLen*2);
   253          }
   254
   255          // insert layer data to raw packet
   256          int indexToInsertData = 0;
   257          if (prevLayer != nullptr)
   258                  indexToInsertData = prevLayer->m_Data + prevLayer->getHeaderLen() - m_RawPacket->getRawData();
   259          m_RawPacket->insertData(indexToInsertData, newLayer->m_Data, newLayerHeaderLen);
   260
   261          //delete previous layer data
   262          delete[] newLayer->m_Data;
   263
   264          // add layer to layers linked list
   265          if (prevLayer != nullptr)
   266          {
   267                  newLayer->setNextLayer(prevLayer->getNextLayer());
   268                  newLayer->setPrevLayer(prevLayer);
   269                  prevLayer->setNextLayer(newLayer);
   270          }
   271          else //prevLayer == NULL
   272          {
   273                  newLayer->setNextLayer(m_FirstLayer);
   274                  if (m_FirstLayer != nullptr)
   275                          m_FirstLayer->setPrevLayer(newLayer);
   276                  m_FirstLayer = newLayer;
   277          }
   278
   279          if (newLayer->getNextLayer() == nullptr)
   280                  m_LastLayer = newLayer;
   281          else
   282                  newLayer->getNextLayer()->setPrevLayer(newLayer);
   283
   284          // assign layer with this packet only
   285          newLayer->m_Packet = this;
   286
   287          // Set flag to indicate if new layer is allocated to packet.
   288          if(ownInPacket)
   289             newLayer->m_IsAllocatedInPacket = true;
   290
   291          // re-calculate all layers data ptr and data length
   292
   293          // first, get ptr and data length of the raw packet
   294          const uint8_t* dataPtr = m_RawPacket->getRawData();
   295          size_t dataLen = (size_t)m_RawPacket->getRawDataLen();
   296
   297          // if a packet trailer exists, get its length
   298          size_t packetTrailerLen = 0;
   299          if (m_LastLayer != nullptr && m_LastLayer->getProtocol() == PacketTrailer)
   300                  packetTrailerLen = m_LastLayer->getDataLen();
   301
   302          // go over all layers from the first layer to the last layer and set the data ptr and data length for each one
   303          Layer* curLayer = m_FirstLayer;
   304          while (curLayer != nullptr)
   305          {
   306                  // set data ptr to layer
   307                  curLayer->m_Data = (uint8_t*)dataPtr;
   308
   309                  // there is an assumption here that the packet trailer, if exists, corresponds to the L2 (data link) layers.
   310                  // so if there is a packet trailer and this layer is L2 (data link), set its data length to contain the whole data, including the
   311                  // packet trailer. If this layer is L3-7, exclude the packet trailer from its data length
   312                  if (curLayer->getOsiModelLayer() == OsiModelDataLinkLayer)
   313                          curLayer->m_DataLen = dataLen;
   314                  else
   315                          curLayer->m_DataLen = dataLen - packetTrailerLen;
   316
   317                  // advance data ptr and data length
   318                  dataPtr += curLayer->getHeaderLen();
   319                  dataLen -= curLayer->getHeaderLen();
   320
   321                  // move to next layer
   322                  curLayer = curLayer->getNextLayer();
   323          }
   324
   325          // add layer protocol to protocol collection
   326          m_ProtocolTypes |= newLayer->getProtocol();
   327          return true;
   328  }
